local a=require"system.util"local b=assert(a.argparse({l=false,s=false},...))if#b<2 then error("usage: cmp [-ls] <file1> <file2>")end;local c,d;if b[1]=="-"then c=io.stdin else c=io.open(b[1],"rb")end;if b[2]=="-"then d=io.stdin else d=io.open(b[2],"rb")end;local function e(f)if c~=io.stdin then c:close()end;if d~=io.stdin then d:close()end;return f end;if c==d then return e(0)end;local g,h=1,0;for i=1,math.huge do local j=c:read(1)local k=d:read(1)if j~=k then h=1;if not j then if not b.s then io.stderr:write("cmp: EOF on "..b[1].."\n")end elseif not k then if not b.s then io.stderr:write("cmp: EOF on "..b[2].."\n")end elseif not b.s then if b.l then io.write(i.." "..j.." "..k.."\n")else io.write(("%s %s differ: char %d, line %d\n"):format(b[1],b[2],i,g))end end;if not b.l then return e(1)end end;if j=="\n"then g=g+1 end;if not j or not k then break end end;return e(h)
